import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import '../../core/validators/app_validators.dart';
import '../../data/models/app_enums.dart';
import '../../widgets/app_text_field.dart';
import 'auth_controller.dart';
class RegisterScreen extends ConsumerStatefulWidget { const RegisterScreen({super.key}); @override ConsumerState<RegisterScreen> createState()=>_RegisterScreenState(); }
class _RegisterScreenState extends ConsumerState<RegisterScreen>{ final _form=GlobalKey<FormState>(); final _name=TextEditingController(),_email=TextEditingController(),_password=TextEditingController(),_confirmation=TextEditingController(); UserRole _role=UserRole.student; @override void dispose(){for(final c in [_name,_email,_password,_confirmation]){c.dispose();}super.dispose();} @override Widget build(BuildContext context){final loading=ref.watch(authControllerProvider).isLoading;return Scaffold(appBar:AppBar(title:const Text('إنشاء حساب')),body:SafeArea(child:ListView(padding:const EdgeInsets.all(24),children:[Form(key:_form,child:Column(children:[AppTextField(controller:_name,label:'الاسم الكامل',validator:(v)=>AppValidators.requiredField(v,'الاسم')),const SizedBox(height:12),AppTextField(controller:_email,label:'البريد الإلكتروني',validator:AppValidators.email),const SizedBox(height:12),AppTextField(controller:_password,label:'كلمة المرور',obscureText:true,validator:AppValidators.password),const SizedBox(height:12),AppTextField(controller:_confirmation,label:'تأكيد كلمة المرور',obscureText:true,validator:(v)=>AppValidators.confirmPassword(v,_password.text)),const SizedBox(height:16),DropdownButtonFormField<UserRole>(value:_role,items:const [DropdownMenuItem(value:UserRole.student,child:Text('طالب')),DropdownMenuItem(value:UserRole.advisor,child:Text('مستشار تعليمي'))],onChanged:(value)=>setState(()=>_role=value!),decoration:const InputDecoration(labelText:'نوع الحساب')),const SizedBox(height:24),FilledButton(onPressed:loading?null:() async {if(!_form.currentState!.validate())return;await ref.read(authControllerProvider.notifier).register(name:_name.text.trim(),email:_email.text.trim(),password:_password.text,role:_role);if(mounted)Navigator.pop(context);},child:loading?const CircularProgressIndicator():const Text('إنشاء الحساب'))])])}));}}
